import XCTest
@testable import YomiKit

/// Backup parsing tests. Fixtures are produced by an independent Python
/// implementation (hand-rolled protobuf encoder + Python gzip) so these tests
/// cross-validate the Swift decoders rather than only round-tripping.
final class BackupParsingTests: XCTestCase {

    // Generated by ios/tools fixtures script (see IOS_TEST_RESULTS.md).
    static let fixtureGzipBase64 = """
    
    """

    private func fixtureData() throws -> Data {
        let cleaned = Self.fixtureGzipBase64
            .components(separatedBy: .whitespacesAndNewlines)
            .joined()
        guard let data = Data(base64Encoded: cleaned) else {
            throw XCTSkip("fixture missing")
        }
        return data
    }

    func testParsesForeignGzippedBackup() throws {
        let backup = try BackupCodec.decode(fixtureData())

        XCTAssertEqual(backup.mangas.count, 2)
        XCTAssertEqual(backup.categories.count, 2)
        XCTAssertEqual(backup.sources.count, 2)
        XCTAssertEqual(backup.skippedPreferenceCount, 2)
        XCTAssertEqual(backup.skippedSourcePreferenceCount, 1)
        XCTAssertEqual(backup.skippedExtensionStoreCount, 1)
    }

    func testDecodesMangaFields() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let manga = try XCTUnwrap(backup.mangas.first)

        XCTAssertEqual(manga.source, 2892384474472123153)
        XCTAssertEqual(manga.url, "manga/alpha")
        XCTAssertEqual(manga.title, "Alpha Chronicle")
        XCTAssertEqual(manga.artist, "Artist A")
        XCTAssertEqual(manga.author, "Author B")
        XCTAssertEqual(manga.mangaDescription, "A description of Alpha.")
        XCTAssertEqual(manga.genres, ["Action", "Drama"])
        XCTAssertEqual(manga.status, 2)
        XCTAssertEqual(manga.thumbnailURL, "https://example.org/alpha.png")
        XCTAssertEqual(manga.dateAdded, 1700000000000)
        XCTAssertEqual(manga.viewer, 2)
        XCTAssertEqual(manga.categories, [3, 7])
        XCTAssertTrue(manga.favorite)
        XCTAssertEqual(manga.chapterFlags, 5)
        XCTAssertEqual(manga.viewerFlags, 1)
        XCTAssertEqual(manga.updateStrategy, 1)
        XCTAssertEqual(manga.favoriteModifiedAt, 1700000000)
        XCTAssertEqual(manga.excludedScanlators, ["Eclipse Team"])
        XCTAssertEqual(manga.notes, "my notes")
        XCTAssertTrue(manga.initialized)
    }

    func testDecodesChaptersWithFloatChapterNumbers() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let chapters = try XCTUnwrap(backup.mangas.first?.chapters)

        XCTAssertEqual(chapters.count, 2)
        XCTAssertEqual(chapters[0].url, "manga/alpha/chapter-1")
        XCTAssertEqual(chapters[0].name, "Chapter 1")
        XCTAssertEqual(chapters[0].scanlator, "Sample Scanlators")
        XCTAssertTrue(chapters[0].read)
        XCTAssertFalse(chapters[0].bookmark)
        XCTAssertEqual(chapters[0].lastPageRead, 3)
        XCTAssertEqual(chapters[0].dateFetch, 1700000000000)
        XCTAssertEqual(chapters[0].dateUpload, 1690000000000)
        XCTAssertEqual(chapters[0].chapterNumber, 12.5)
        XCTAssertEqual(chapters[0].sourceOrder, 0)

        XCTAssertEqual(chapters[1].name, "Chapter 2")
        XCTAssertEqual(chapters[1].chapterNumber, 2.0)
        XCTAssertEqual(chapters[1].sourceOrder, 1)
    }

    func testDecodesTrackingAndHistory() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let tracking = try XCTUnwrap(backup.mangas.first?.tracking.first)
        XCTAssertEqual(tracking.syncId, 2)
        XCTAssertEqual(tracking.libraryId, 987654)
        XCTAssertEqual(tracking.mediaId, 555444)
        XCTAssertEqual(tracking.title, "Alpha Chronicle")
        XCTAssertEqual(tracking.lastChapterRead, 3.0)
        XCTAssertEqual(tracking.score, 8.5)

        let history = try XCTUnwrap(backup.mangas.first?.history.first)
        XCTAssertEqual(history.url, "manga/alpha/chapter-1")
        XCTAssertEqual(history.lastRead, 1700000123000)
        XCTAssertEqual(history.readDuration, 61000)
    }

    func testSkipsUnknownFieldsWithoutFailing() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let beta = try XCTUnwrap(backup.mangas.last)
        XCTAssertEqual(beta.url, "manga/beta")
        XCTAssertEqual(beta.title, "Beta Saga")
        XCTAssertTrue(beta.favorite)
    }

    func testExportRoundTrip() throws {
        let original = try BackupCodec.decode(fixtureData())
        let encoded = BackupCodec.encodeGzipped(original)
        let decoded = try BackupCodec.decode(encoded)

        XCTAssertEqual(decoded.mangas, original.mangas)
        XCTAssertEqual(decoded.categories, original.categories)
        XCTAssertEqual(decoded.sources, original.sources)
    }

    func testGzippedAndRawInputsBothParse() throws {
        let gz = try fixtureData()
        let raw = try Gzip.decompress(gz)
        let fromRaw = try BackupCodec.decode(raw)
        let fromGz = try BackupCodec.decode(gz)
        XCTAssertEqual(fromRaw, fromGz)
    }

    func testInvalidDataThrows() {
        XCTAssertThrowsError(try BackupCodec.decode(Data([0xff, 0x00, 0x01])))
    }

    func testInspectReportsMissingSourcesAndSkippedSections() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let known: [SourceID] = [SourceID(rawValue: 2892384474472123153)]
        let report = BackupImporter.inspect(backup, knownSources: known)

        XCTAssertEqual(report.mangaCount, 2)
        XCTAssertEqual(report.chapterCount, 2)
        XCTAssertEqual(report.categoryCount, 2)
        XCTAssertEqual(report.historyCount, 1)
        XCTAssertEqual(report.trackingCount, 1)

        XCTAssertEqual(report.sources.count, 2)
        XCTAssertEqual(report.missingSources.map(\.sourceId), [42])
        XCTAssertEqual(report.missingSources.first?.name, "Gone Source")
        XCTAssertTrue(report.skippedSections.contains { $0.contains("2 app preference") })
        XCTAssertTrue(report.skippedSections.contains { $0.contains("extension store") })
    }

    func testPlanBuildsAdditiveEntries() throws {
        let backup = try BackupCodec.decode(fixtureData())
        let plan = BackupImporter.plan(backup)

        XCTAssertEqual(plan.mangas.count, 2)
        XCTAssertEqual(plan.categories.map(\.name), ["Reading", "Favorites"])
        XCTAssertEqual(plan.mangas[0].categoryRefs, [3, 7])
        XCTAssertEqual(plan.mangas[0].chapters.count, 2)
        XCTAssertEqual(plan.history.count, 1)
        XCTAssertEqual(plan.history[0].chapterURL, "manga/alpha/chapter-1")
    }

    func testApplyNeverDeletesExistingData() async throws {
        let store = try LibraryStore.inMemory()
        // Pre-existing manga that is NOT in the backup
        let preExisting = try await store.upsertManga(
            Manga(sourceID: SourceID(rawValue: 7), url: "keep/me", title: "Keep Me", favoriteAt: Date())
        )
        XCTAssertEqual(preExisting.id, 1)

        let backup = try BackupCodec.decode(fixtureData())
        let result = try await store.apply(BackupImporter.plan(backup))

        XCTAssertEqual(result.addedManga, 2)
        XCTAssertEqual(result.addedChapters, 2)
        XCTAssertEqual(result.addedCategories, 2)

        let kept = await store.manga(sourceID: SourceID(rawValue: 7), url: "keep/me")
        XCTAssertNotNil(kept, "Import must never delete existing data")

        let restored = await store.manga(sourceID: SourceID(rawValue: 42), url: "manga/beta")
        XCTAssertNotNil(restored, "Manga from unavailable sources are still imported")
        let betaChapters = await store.chapters(mangaID: restored!.id)
        XCTAssertTrue(betaChapters.isEmpty)
    }

    func testReimportIsIdempotent() async throws {
        let store = try LibraryStore.inMemory()
        let backup = try BackupCodec.decode(fixtureData())
        let plan = BackupImporter.plan(backup)

        _ = try await store.apply(plan)
        let second = try await store.apply(plan)

        XCTAssertEqual(second.addedManga, 0, "Re-import merges instead of duplicating")
        XCTAssertEqual(second.mergedManga, 2)

        let alpha = await store.manga(sourceID: SourceID(rawValue: 2892384474472123153), url: "manga/alpha")
        XCTAssertNotNil(alpha)
        let chapters = await store.chapters(mangaID: alpha!.id)
        XCTAssertEqual(chapters.count, 2, "Chapters merge by URL")
    }

    func testProgressRestoredOnImport() async throws {
        let store = try LibraryStore.inMemory()
        let backup = try BackupCodec.decode(fixtureData())
        try await store.apply(BackupImporter.plan(backup))

        let alpha = await store.manga(sourceID: SourceID(rawValue: 2892384474472123153), url: "manga/alpha")!
        let chapters = await store.chapters(mangaID: alpha.id)
        XCTAssertTrue(chapters[0].read)
        XCTAssertEqual(chapters[0].lastPageRead, 3)
        XCTAssertFalse(chapters[1].read)
    }
}
